-- Persistent, recipient-scoped in-app notifications.
-- Notifications are generated by trusted database triggers, never by browser-supplied recipients.

create table if not exists public.notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  event_type text not null,
  title text not null,
  body text not null,
  href text not null default '/',
  metadata jsonb not null default '{}'::jsonb,
  dedupe_key text not null unique,
  created_at timestamptz not null default now(),
  read_at timestamptz
);

create index if not exists notifications_user_created_idx
  on public.notifications(user_id, created_at desc);
create index if not exists notifications_user_unread_idx
  on public.notifications(user_id, created_at desc)
  where read_at is null;

alter table public.notifications enable row level security;
revoke all on public.notifications from anon, authenticated;
grant select on public.notifications to authenticated;
grant update (read_at) on public.notifications to authenticated;

create policy "Users can read their own notifications"
  on public.notifications for select to authenticated
  using (user_id = (select auth.uid()));

create policy "Users can mark their own notifications as read"
  on public.notifications for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create or replace function private.create_order_notifications()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_fisher_id uuid;
  v_recipient_id uuid;
  v_event_type text;
  v_title text;
  v_body text;
  v_href text;
  v_dedupe_key text;
begin
  select c.fisher_id into v_fisher_id
  from public.catches c
  where c.id = new.catch_id;

  if v_fisher_id is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    insert into public.notifications
      (user_id, event_type, title, body, href, metadata, dedupe_key)
    values
      (v_fisher_id, 'order_received', 'Nouvelle commande reçue',
       'Un restaurant vient de réserver une prise.', '/espace-pecheur',
       jsonb_build_object('order_id', new.id, 'catch_id', new.catch_id),
       'order:' || new.id::text || ':created:' || v_fisher_id::text)
    on conflict (dedupe_key) do nothing;
    return new;
  end if;

  if old.status is distinct from new.status then
    if (select auth.uid()) = new.restaurant_id then
      v_recipient_id := v_fisher_id;
      v_event_type := 'order_status_changed';
      v_title := 'Commande mise à jour';
      v_body := 'Le restaurant a mis à jour une commande.';
      v_href := '/espace-pecheur';
    else
      v_recipient_id := new.restaurant_id;
      v_event_type := 'order_status_changed';
      v_title := 'Commande mise à jour';
      v_body := 'Le statut de votre commande vient de changer.';
      v_href := '/restaurant';
    end if;

    insert into public.notifications
      (user_id, event_type, title, body, href, metadata, dedupe_key)
    values
      (v_recipient_id, v_event_type, v_title, v_body, v_href,
       jsonb_build_object('order_id', new.id, 'catch_id', new.catch_id, 'status', new.status),
       'order:' || new.id::text || ':status:' || new.status::text || ':' || v_recipient_id::text)
    on conflict (dedupe_key) do nothing;
  end if;

  if old.cancellation_request_status is distinct from new.cancellation_request_status then
    if new.cancellation_request_status = 'pending' then
      v_recipient_id := v_fisher_id;
      v_event_type := 'order_cancellation_requested';
      v_title := 'Demande d’annulation reçue';
      v_body := 'Un restaurant demande à annuler une commande.';
      v_href := '/espace-pecheur';
    elsif new.cancellation_request_status in ('offered', 'rejected') then
      v_recipient_id := new.restaurant_id;
      v_event_type := 'order_cancellation_response';
      v_title := 'Réponse à votre demande d’annulation';
      v_body := 'Le pêcheur a répondu à votre demande d’annulation.';
      v_href := '/restaurant';
    else
      v_recipient_id := null;
    end if;

    if v_recipient_id is not null then
      insert into public.notifications
        (user_id, event_type, title, body, href, metadata, dedupe_key)
      values
        (v_recipient_id, v_event_type, v_title, v_body, v_href,
         jsonb_build_object('order_id', new.id, 'catch_id', new.catch_id, 'cancellation_status', new.cancellation_request_status),
         'order:' || new.id::text || ':cancellation:' || new.cancellation_request_status || ':' || v_recipient_id::text)
      on conflict (dedupe_key) do nothing;
    end if;
  end if;

  return new;
end;
$function$;

revoke all on function private.create_order_notifications() from public, anon, authenticated;

drop trigger if exists orders_create_notifications on public.orders;
create trigger orders_create_notifications
  after insert or update of status, cancellation_request_status on public.orders
  for each row execute function private.create_order_notifications();

create or replace function private.create_verification_request_notifications()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
declare
  v_admin_id uuid;
begin
  for v_admin_id in
    select p.id from public.profiles p where p.role = 'admin'::public.app_role
    union
    select au.user_id from private.admin_users au
  loop
    insert into public.notifications
      (user_id, event_type, title, body, href, metadata, dedupe_key)
    values
      (v_admin_id, 'verification_request_received', 'Nouvelle demande de vérification',
       'Un compte attend une vérification par l’administration.', '/admin',
       jsonb_build_object('request_id', new.id, 'user_id', new.user_id, 'requested_role', new.requested_role),
       'verification:' || new.id::text || ':created:' || v_admin_id::text)
    on conflict (dedupe_key) do nothing;
  end loop;
  return new;
end;
$function$;

revoke all on function private.create_verification_request_notifications() from public, anon, authenticated;

drop trigger if exists verification_requests_create_notifications on public.verification_requests;
create trigger verification_requests_create_notifications
  after insert on public.verification_requests
  for each row execute function private.create_verification_request_notifications();

do $publication$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (
       select 1 from pg_publication_tables
       where pubname = 'supabase_realtime'
         and schemaname = 'public'
         and tablename = 'notifications'
     ) then
    execute 'alter publication supabase_realtime add table public.notifications';
  end if;
end;
$publication$;
